package com.bank.durability.policy;

// Explicit loss window per data class — the core discipline.
public enum DurabilityPolicy {
    SYNC_REPLICATED(0),      // RPO=0: acknowledge only after durable + replicated
    BUFFERED_ASYNC(60),      // RPO=60s: may lose up to the buffer window on crash
    VOLATILE(Integer.MAX_VALUE); // may lose entirely; regenerable

    private final int rpoSeconds;
    DurabilityPolicy(int rpoSeconds) { this.rpoSeconds = rpoSeconds; }
    public int rpoSeconds() { return rpoSeconds; }
}
