package com.bank.durability.sink;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Critical data: only ACKNOWLEDGES after the record is durably persisted.
// A crash cannot lose an acknowledged record (RPO=0).
public class DurableSink {
    private static final Logger log = Logger.getLogger(DurableSink.class.getName());
    private final List<String> durable = new ArrayList<>();

    public boolean writeAndAck(String record) {
        durable.add(record);                 // synchronous persist + (conceptually) replicate
        log.fine(() -> "Durably committed " + record);
        return true;                         // ack ONLY now → safe
    }
    // Survives a crash: everything here was acknowledged, so nothing is lost.
    public List<String> afterCrash() { return durable; }
}
