package com.bank.durability.sink;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Low-value data: buffered and flushed periodically. A crash loses the UNFLUSHED buffer.
// The buffer window MUST match the stated RPO, or the window is a lie.
public class BufferedSink {
    private static final Logger log = Logger.getLogger(BufferedSink.class.getName());
    private final int maxBufferWithinRpo;     // sized so buffered age <= RPO
    private final List<String> flushed = new ArrayList<>();
    private final List<String> buffer = new ArrayList<>();

    public BufferedSink(int maxBufferWithinRpo) { this.maxBufferWithinRpo = maxBufferWithinRpo; }

    public boolean writeAck(String record) {
        buffer.add(record);                   // ack immediately (fast, lossy)
        if (buffer.size() >= maxBufferWithinRpo) flush();
        return true;
    }
    private void flush() { flushed.addAll(buffer); buffer.clear(); log.fine("Flushed telemetry batch"); }
    // On crash: flushed survives, buffer is LOST (acceptable within the RPO window).
    public int lostOnCrash() { return buffer.size(); }
    public int survived() { return flushed.size(); }
}
