package com.bank.durability;

import com.bank.durability.policy.DurabilityPolicy;
import com.bank.durability.sink.BufferedSink;
import com.bank.durability.sink.DurableSink;
import java.util.logging.*;

public class DataLossDemo {
    private static final Logger log = Logger.getLogger(DataLossDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        log.info("=== Durability matched to data value (explicit loss windows) ===");

        // CRITICAL: transfers, RPO=0 → DurableSink, acknowledged only when durable.
        DurableSink transfers = new DurableSink();
        for (int i = 1; i <= 5; i++) transfers.writeAndAck("TRF-" + i + " Rs.50000");

        // LOW VALUE: telemetry, RPO=60s → BufferedSink; buffer sized to stay within window.
        BufferedSink telemetry = new BufferedSink(10); // flush every 10 → <=60s of data buffered
        for (int i = 1; i <= 23; i++) telemetry.writeAck("click-" + i);

        // Simulate a CRASH right now.
        log.severe("*** CRASH ***");

        // Report what each class lost against its stated window.
        log.info(() -> "Transfers (RPO=" + DurabilityPolicy.SYNC_REPLICATED.rpoSeconds()
                + "s): survived=" + transfers.afterCrash().size() + " lost=0 zero loss");
        log.info(() -> "Telemetry (RPO=" + DurabilityPolicy.BUFFERED_ASYNC.rpoSeconds()
                + "s): survived=" + telemetry.survived() + " lost=" + telemetry.lostOnCrash()
                + " within window");
        log.info("Cache (VOLATILE): lost entirely — regenerated on next miss, correctness intact");
    }
}

